/// Verifies that a buffer of bytes contains a `CVR`
/// and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_cvr_unchecked`.
#[inline]
pub fn root_as_cvr(buf: &[u8]) -> Result<CVR<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root::<CVR>(buf)
}

/// Verifies that a buffer of bytes contains a size prefixed
/// `CVR` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `size_prefixed_root_as_cvr_unchecked`.
#[inline]
pub fn size_prefixed_root_as_cvr(buf: &[u8]) -> Result<CVR<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root::<CVR>(buf)
}

/// Verifies, with the given options, that a buffer of bytes
/// contains a `CVR` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_cvr_unchecked`.
#[inline]
pub fn root_as_cvr_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<CVR<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root_with_opts::<CVR<'b>>(opts, buf)
}

/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `CVR` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_cvr_unchecked`.
#[inline]
pub fn size_prefixed_root_as_cvr_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<CVR<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root_with_opts::<CVR<'b>>(opts, buf)
}

/// Assumes, without verification, that a buffer of bytes contains a CVR and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `CVR`.
#[inline]
pub unsafe fn root_as_cvr_unchecked(buf: &[u8]) -> CVR<'_> {
    unsafe { ::flatbuffers::root_unchecked::<CVR>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed CVR and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `CVR`.
#[inline]
pub unsafe fn size_prefixed_root_as_cvr_unchecked(buf: &[u8]) -> CVR<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<CVR>(buf) }
}

pub const CVR_IDENTIFIER: &str = "$CVR";

#[inline]
pub fn cvr_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, CVR_IDENTIFIER, false)
}

#[inline]
pub fn cvr_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, CVR_IDENTIFIER, true)
}

#[inline]
pub fn finish_cvr_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<CVR<'a>>
) {
    fbb.finish(root, Some(CVR_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_cvr_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<CVR<'a>>
) {
    fbb.finish_size_prefixed(root, Some(CVR_IDENTIFIER));
}
